INSERT INTO faq (id, question, answer, createdAt) VALUES
('9bd4b1aa-59fd-4b68-84a4-45d1cb7b4ece', 'Why are my chests opening/closing?! Am I being followed by ghosts?', 'No worries! It''s just the mod scanning the shop contents - it''s to be expected.', '2026-07-24T20:05:43.364Z'),
('5d4932ad-69f0-42c7-927d-9b76c4904769', 'How do I fix HTML error 301/302?', 'Update your mod to version 1.2.3 or higher by downloading the newest version from the website.', '2026-07-27T11:41:42.164Z'),
('3b11ac4c-8bc4-49ee-9f94-5128495fc154', 'How do I fix error 1102?', 'Please ping or DM me on discord (@ectf/@maxolotled) so I can fix it!', '2026-07-27T11:42:56.891Z'),
